def compare_one(a, b):
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return max(a, b)
    elif isinstance(a, str) and a.endswith(",") or a.endswith("."):
        return max(float(a), 0.0)
    else:
        return None
